#define CHECK_MEM_ERROR(error, lval, expr)                                  \
  do {                                                                      \
    assert((error)->setjmp);                                                \
    (lval) = (expr);                                                        \
    if (!(lval))                                                            \
      vpx_internal_error(error, VPX_CODEC_MEM_ERROR,                        \
                         "Failed to allocate " #lval " at %s:%d", __FILE__, \
                         __LINE__);                                         \
  } while (0)
#else
#define CHECK_MEM_ERROR(error, lval, expr)             \
  do {                                                 \
    assert((error)->setjmp);                           \
    (lval) = (expr);                                   \
    if (!(lval))                                       \
      vpx_internal_error(error, VPX_CODEC_MEM_ERROR,   \
                         "Failed to allocate " #lval); \
